llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Levomepromazine, the closest analogue sharing the methoxyphenyl and dimethylaminoethyl pharmacophore, showed 33–74% oral systemic availability in patients, directly supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Imipramine, a tricyclic with the same dimethylaminopropyl side chain, had absolute oral bioavailability of approximately 40% in control subjects, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Promethazine, a related tricyclic with a dimethylaminoisopropyl side chain, had absolute oral bioavailability of 25% in healthy volunteers, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Chlorimipramine, a chloro-substituted tricyclic analogue, showed absolute oral bioavailability ranging 36–68% (mean 48%) in healthy volunteers, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Eslicarbazepine acetate, which also contains an acetate ester, showed >90% oral bioavailability in humans, indicating that the ester moiety does not preclude high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a benzothiazepine (diltiazem-like) with a basic dimethylaminoethyl side chain and an acetate ester. Multiple transferable analogues with the same tricyclic/amine pharmacophore show absolute oral bioavailability of 25–74%, all above the 20% threshold; the closest analogue (levomepromazine) and tricyclic antidepressants support high F. The weak contradictory signals (prothipendyl, aniracetam) are distant and not threshold-quantified, so the prediction is high.",
  "evidence_gaps": [
    "No direct diltiazem bioavailability record is present in the evidence set; the closest analogues have moderate Morgan similarity (0.22–0.34).",
    "The modified-release formulation condition is not directly represented in the analogue records; modified release may alter absorption kinetics but is not expected to reduce extent below 20%.",
    "Prothipendyl is reported only as 'low' without a quantitative F, so it was not used as affirmative evidence for low bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

